<?php
namespace App\Http\Controllers;
use App\Models\ActivityLog;
use App\Models\CurrencyExchange;
use App\Models\DocumentSequence;
use App\Models\ExchangeRate;
use App\Models\FinancialAccount;
use App\Models\JournalEntry;
use App\Models\LedgerAccount;
use App\Services\Accounting\JournalPostingService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class CurrencyExchangeController extends Controller {
 public function index(Request $request){abort_unless($request->user()->can('administration.view'),403);return view('finance.exchanges.index',['exchanges'=>CurrencyExchange::with(['source','destination','sourceCurrency','destinationCurrency','sourceJournal','destinationJournal'])->latest()->paginate(25)->withQueryString(),'accounts'=>FinancialAccount::with('currency')->where('is_active',true)->orderBy('name')->get(),'rates'=>ExchangeRate::with(['fromCurrency','toCurrency'])->latest('effective_date')->limit(100)->get()]);}
 public function store(Request $request,JournalPostingService $posting){abort_unless($request->user()->can('administration.update'),403);$data=$request->validate(['exchange_type'=>['required','in:internal,external'],'provider_name'=>['required_if:exchange_type,external','nullable','string','max:200'],'provider_contact'=>['nullable','string','max:150'],'exchange_date'=>['required','date'],'source_account_id'=>['required','exists:financial_accounts,id'],'destination_account_id'=>['required','exists:financial_accounts,id','different:source_account_id'],'source_amount'=>['required','numeric','gt:0','decimal:0,4'],'destination_amount'=>['required','numeric','gt:0','decimal:0,4'],'applied_rate'=>['required','numeric','gt:0','decimal:0,12'],'reference_rate_id'=>['nullable','exists:exchange_rates,id'],'reference'=>['nullable','string','max:100'],'description'=>['required','string','max:2000']]);
  DB::transaction(function()use($data,$request,$posting){$source=FinancialAccount::whereKey($data['source_account_id'])->lockForUpdate()->firstOrFail();$destination=FinancialAccount::whereKey($data['destination_account_id'])->lockForUpdate()->firstOrFail();if(!$source->is_active||!$destination->is_active||$source->currency_id===$destination->currency_id)throw ValidationException::withMessages(['destination_account_id'=>'Choose active accounts in different currencies.']);
   $rate=isset($data['reference_rate_id'])?ExchangeRate::findOrFail($data['reference_rate_id']):null;if($rate&&($rate->from_currency_id!==$source->currency_id||$rate->to_currency_id!==$destination->currency_id||$rate->effective_date->toDateString()>$data['exchange_date']))throw ValidationException::withMessages(['reference_rate_id'=>'Reference rate must match the currency direction and not be dated after the exchange.']);
   // The entered received amount and applied rate must agree within destination rounding precision.
   $expected=(float)$data['source_amount']*(float)$data['applied_rate'];if(abs($expected-(float)$data['destination_amount'])>0.00011)throw ValidationException::withMessages(['destination_amount'=>'Received amount must equal source amount multiplied by applied rate (four-decimal precision).']);
   $linked=function(FinancialAccount $account){$id=DB::table('entity_ledger_accounts')->where(['entity_type'=>$account->type,'entity_id'=>$account->id,'currency_id'=>$account->currency_id,'purpose'=>'cash'])->value('ledger_account_id');$ledger=$id?LedgerAccount::find($id):null;if(!$ledger||!$ledger->is_active||$ledger->is_group)throw ValidationException::withMessages(['source_account_id'=>'A financial account is missing its active posting ledger.']);return $ledger->id;};
   // Currency-specific clearing accounts avoid falsely equating unlike monetary units.
   $clearing=function(int $currencyId){$currency=\App\Models\Currency::findOrFail($currencyId);$parent=LedgerAccount::where('code','1120')->firstOrFail();if(!$parent->is_group||!$parent->is_active)throw ValidationException::withMessages(['source_account_id'=>'Trade Receivables (1120) must be an active group for FX clearing.']);return LedgerAccount::firstOrCreate(['code'=>'1120.FX.'.$currency->code],['name'=>'FX Clearing — '.$currency->code,'type'=>'asset','parent_id'=>$parent->id,'is_group'=>false,'is_active'=>true,'description'=>'Currency-specific clearing for exchange transactions']);};
   DocumentSequence::firstOrCreate(['document_type'=>'currency_exchange'],['prefix'=>'FX-','next_number'=>1,'padding'=>6,'is_active'=>true]);$number=DocumentSequence::issue('currency_exchange');$journals=[];
   foreach([['currency'=>$source->currency_id,'amount'=>$data['source_amount'],'debit'=>$clearing($source->currency_id)->id,'credit'=>$linked($source),'suffix'=>'-OUT'],['currency'=>$destination->currency_id,'amount'=>$data['destination_amount'],'debit'=>$linked($destination),'credit'=>$clearing($destination->currency_id)->id,'suffix'=>'-IN']] as $side){$journal=JournalEntry::create(['number'=>$number.$side['suffix'],'entry_date'=>$data['exchange_date'],'reference'=>$data['reference']??null,'description'=>'Currency exchange '.$number.': '.$data['description'],'status'=>'draft','currency_id'=>$side['currency'],'created_by'=>$request->user()->id]);$journal->lines()->create(['ledger_account_id'=>$side['debit'],'debit'=>$side['amount'],'credit'=>0]);$journal->lines()->create(['ledger_account_id'=>$side['credit'],'debit'=>0,'credit'=>$side['amount']]);$posting->post($journal,$request->user()->id);$journals[]=$journal;}
   $exchange=CurrencyExchange::create(['exchange_type'=>$data['exchange_type'],'provider_name'=>$data['exchange_type']==='external'?$data['provider_name']:null,'provider_contact'=>$data['exchange_type']==='external'?($data['provider_contact']??null):null,'exchange_date'=>$data['exchange_date'],'source_account_id'=>$source->id,'destination_account_id'=>$destination->id,'source_currency_id'=>$source->currency_id,'destination_currency_id'=>$destination->currency_id,'source_amount'=>$data['source_amount'],'destination_amount'=>$data['destination_amount'],'applied_rate'=>$data['applied_rate'],'reference_rate_id'=>$rate?->id,'reference'=>$data['reference']??null,'description'=>$data['description'],'source_journal_id'=>$journals[0]->id,'destination_journal_id'=>$journals[1]->id,'created_by'=>$request->user()->id]);ActivityLog::record('currency_exchange.posted','currency_exchange',$exchange->id,'Currency exchange '.$number.' posted');
  });return redirect()->route('finance.exchanges.index')->with('status','Currency exchange posted with two currency-specific journals.');}
}
